namespace IslandIntegrated {
 public static class StatusPerformance {
  static string P(double? value){return value.HasValue&&!Double.IsNaN(value.Value)&&!Double.IsInfinity(value.Value)&&value>=0&&value<=100?value.Value.ToString("0.0")+"%":"\u2014";}
  public static string[] Pages(LegacySnapshot s){if(s==null||!s.IsFresh(DateTimeOffset.UtcNow))return new[]{"\u7b49\u5f85\u6027\u80fd\u6570\u636e"};return new[]{"CPU Utility "+P(s.Cpu)+"  \u00b7  \u5185\u5b58 "+P(s.Memory),"C "+P(s.DiskC)+"  \u00b7  D "+P(s.DiskD),"GPU "+P(s.Gpu)+(s.GpuUsedMb.HasValue&&s.GpuTotalMb.HasValue?"  "+(s.GpuUsedMb.Value/1024).ToString("0.0")+"/"+(s.GpuTotalMb.Value/1024).ToString("0.#")+" GiB":"")};}
  public static void PaintTicker(Graphics g,RectangleF bounds,Font font,Color color,string current,string next,double progress){var saved=g.Save();g.SetClip(bounds,CombineMode.Intersect);float p=(float)Math.Max(0,Math.Min(1,progress));p=p*p*(3-2*p);using(var b=new SolidBrush(color))using(var format=new StringFormat{FormatFlags=StringFormatFlags.NoWrap,Trimming=StringTrimming.EllipsisCharacter,LineAlignment=StringAlignment.Center}){var a=bounds;a.Y-=p*bounds.Height;g.DrawString(current??"",font,b,a,format);if(p>0&&!String.IsNullOrEmpty(next)){a=bounds;a.Y+=(1-p)*bounds.Height;g.DrawString(next,font,b,a,format);}}g.Restore(saved);}
 }
 public static class StatusHints {
  public static string At(Point p,int width,bool compact,LegacySnapshot data){if(new Rectangle(5,12,17,44).Contains(p))return StatusSignal.From(data).Text;if(StatusUiLayout.CcSwitchButton(width,compact).Contains(p))return "启动 CC Switch";if(!compact&&StatusUiLayout.ThemeButton(width).Contains(p))return "切换主题";if(StatusDockState.CollapseButton(width).Contains(p))return "\u6536\u8d77\u72b6\u6001\u53f0";if(!compact&&StatusUiLayout.WebsiteTestHit(width).Contains(p))return "网站访问耗时："+WebsiteLatency.Label(DateTimeOffset.UtcNow)+"；点击测速，每 5 分钟自动刷新";if(!compact&&StatusUiLayout.Connection(1,width).Contains(p))return data!=null&&data.Balance.Fresh(DateTimeOffset.UtcNow)?"DeepSeek "+data.Balance.Currency+" "+data.Balance.Total.Value.ToString("0.00")+(data.Balance.Available?"":" · \u8d26\u6237\u4e0d\u53ef\u7528"):"DeepSeek \u4f59\u989d\u672a\u63a5\u5165\u6216\u5df2\u8fc7\u671f\uff0c\u672a\u8bfb\u53d6\u51ed\u636e";for(int i=0;i<2;i++){if((compact?StatusUiLayout.ServiceIcon(i,width,CornerLayout.CompactHeight):StatusUiLayout.Service(i,width)).Contains(p))return StatusUiRenderer.DesktopAgentHint(data,i,DateTimeOffset.UtcNow);if(!compact&&StatusUiLayout.Voice(i,width).Contains(p))return (i==0?"Codex":"Claude")+"\u914d\u97f3\uff1a\u70b9\u51fb\u5207\u6362\u5e76\u8bd5\u542c";}return "";}
 }
 public sealed class DockHoverMotion {
  public float Amount {get;private set;}long last=-1;public bool Step(bool inside,long now,bool reduced){float target=inside?1:0,old=Amount;if(last<0||reduced){Amount=target;last=now;return old!=Amount;}float elapsed=Math.Max(0,Math.Min(80,now-last));last=now;float k=1-(float)Math.Exp(-elapsed/55f);Amount+=(target-Amount)*k;if(Math.Abs(target-Amount)<.004f)Amount=target;return old!=Amount;}
 }
 public static class VoiceSample {
  static void Safe(string path){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p)){if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Redirected voice pack");}}
  public static double Volume(string root){try{string file=Path.Combine(root,"config.json");Safe(file);if(new FileInfo(file).Length>1048576)return .4;var d=new JavaScriptSerializer{MaxJsonLength=1048576}.DeserializeObject(File.ReadAllText(file)) as IDictionary<string,object>;object v;if(d!=null&&d.TryGetValue("volume",out v)&&v!=null&&!(v is bool)){double n=Convert.ToDouble(v,System.Globalization.CultureInfo.InvariantCulture);if(!Double.IsNaN(n)&&!Double.IsInfinity(n))return Math.Max(0,Math.Min(1,n));}}catch{}return .4;}
  public static string Resolve(string root,string pack){if(String.IsNullOrWhiteSpace(pack)||pack.IndexOfAny(new[]{'\\','/',':'} )>=0||pack=="."||pack=="..")throw new IOException("Invalid voice pack");string folder=Path.GetFullPath(Path.Combine(root,"packs",pack)),manifest=Path.Combine(folder,"openpeon.json");Safe(manifest);if(!File.Exists(manifest)||new FileInfo(manifest).Length>1048576)throw new IOException("Voice greeting unavailable");var d=new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=16}.DeserializeObject(File.ReadAllText(manifest)) as IDictionary<string,object>;object categories,start,sounds;if(d==null||!d.TryGetValue("categories",out categories)||!(categories is IDictionary<string,object>)||!((IDictionary<string,object>)categories).TryGetValue("session.start",out start)||!(start is IDictionary<string,object>)||!((IDictionary<string,object>)start).TryGetValue("sounds",out sounds)||!(sounds is IList))throw new IOException("Voice greeting unavailable");string prefix=folder+Path.DirectorySeparatorChar;foreach(var row in (IList)sounds){var item=row as IDictionary<string,object>;object value;if(item==null||!item.TryGetValue("file",out value)||!(value is string))continue;string rel=(string)value;if(Path.IsPathRooted(rel)||rel.Contains(':'))continue;string file=Path.GetFullPath(Path.Combine(folder,rel));if(!file.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))continue;Safe(file);var ext=Path.GetExtension(file).ToLowerInvariant();if((ext==".mp3"||ext==".wav"||ext==".wma")&&File.Exists(file)&&new FileInfo(file).Length<=8388608)return file;}throw new IOException("No supported greeting in selected pack");}
 }
 public sealed class VoiceSwitchResult {public string Pack;public bool Saved,PreviewStarted,Duplicate;}
 public sealed class VoiceSwitchGate {
  readonly Dictionary<string,long> clicks=new Dictionary<string,long>();
  public VoiceSwitchResult Switch(string ide,long now,Func<string> save,Action<string> preview){long last;if(clicks.TryGetValue(ide,out last)&&now-last>=0&&now-last<350)return new VoiceSwitchResult{Duplicate=true};clicks[ide]=now;string pack=save();var result=new VoiceSwitchResult{Pack=pack,Saved=true};try{preview(pack);result.PreviewStarted=true;}catch{}return result;}
 }
 public static class VoicePreview {
  static readonly VoiceSwitchGate gate=new VoiceSwitchGate();static System.Windows.Media.MediaPlayer player;static System.Windows.Forms.Timer stop;
  public static VoiceSwitchResult SwitchNext(string ide){return gate.Switch(ide,PreviewClock.NowMs,()=>VoicePackStore.SelectNext(ide),pack=>Play(VoiceSample.Resolve(VoicePackStore.DefaultRoot,pack),VoiceSample.Volume(VoicePackStore.DefaultRoot)));}
  static void Play(string file,double volume){if(stop!=null){stop.Stop();stop.Dispose();stop=null;}if(player!=null){player.Stop();player.Close();}player=new System.Windows.Media.MediaPlayer();player.Volume=volume;player.Open(new Uri(file,UriKind.Absolute));player.Play();stop=new System.Windows.Forms.Timer{Interval=7000};stop.Tick+=(s,e)=>{stop.Stop();if(player!=null){player.Stop();player.Close();}};stop.Start();}
  public static void Close(){if(stop!=null){stop.Stop();stop.Dispose();stop=null;}if(player!=null){player.Stop();player.Close();player=null;}}
 }
 public sealed class RouteSelection {
  readonly NetworkReadonlySnapshot data;public string Selected {get;private set;}public RouteSelection(NetworkReadonlySnapshot value){data=value??new NetworkReadonlySnapshot();}
  public bool Select(string name,DateTimeOffset now){if(!data.CanPreview(now)||String.IsNullOrEmpty(data.Group)||Array.IndexOf(data.Choices,name)<0)return false;Selected=name;return true;}
  public bool NeedsChange {get{return !String.IsNullOrEmpty(Selected)&&Selected!=data.Current;}}
  public string Confirmation {get{return NeedsChange?data.Current+" \u2192 "+Selected:"";}}
 }
 public static class NeteaseWindow {
  public sealed class WindowCandidate {public IntPtr Handle;public int ProcessId,Width,Height;public string ClassName,Title;public bool Owned,Child,Visible;}
  delegate bool EnumWindow(IntPtr window,IntPtr parameter);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool EnumWindows(EnumWindow callback,IntPtr parameter);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint process);
  [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern int GetWindowText(IntPtr window,System.Text.StringBuilder text,int capacity);
  [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern int GetClassName(IntPtr window,System.Text.StringBuilder text,int capacity);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr window,out Native.RECT rect);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool IsIconic(IntPtr window);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern IntPtr GetWindow(IntPtr window,uint command);
  [System.Runtime.InteropServices.DllImport("user32.dll",EntryPoint="GetWindowLongW")]static extern int GetWindowLong(IntPtr window,int index);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool ShowWindowAsync(IntPtr window,int command);
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr window);
  [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct Placement {public uint Length,Flags,Show;public System.Drawing.Point Min,Max;public Native.RECT Normal;}
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool GetWindowPlacement(IntPtr window,ref Placement placement);
  public static Func<string,bool> OpenInstalled=(path)=>{var p=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});if(p!=null)p.Dispose();return true;};
  public static Func<string,bool?> RaiseRunning=TryRaise;
  // Restrict restoration to the known NetEase main-host class. Never surface a
  // hidden CEF utility/renderer window, a plugin dialog or an unidentified blank.
  public static IntPtr SelectMainWindow(IEnumerable<WindowCandidate> windows,ISet<int> allowed){WindowCandidate visible=null,hidden=null;int visibleCount=0,hiddenCount=0;foreach(var w in windows){if(w==null||w.Handle==IntPtr.Zero||!allowed.Contains(w.ProcessId)||w.Owned||w.Child||w.ClassName!="OrpheusBrowserHost"||String.IsNullOrWhiteSpace(w.Title)||w.Title.StartsWith("BetterNCM",StringComparison.OrdinalIgnoreCase)||w.Width<320||w.Height<240)continue;if(w.Visible){visible=w;visibleCount++;}else{hidden=w;hiddenCount++;}}return visibleCount==1?visible.Handle:visibleCount==0&&hiddenCount==1?hidden.Handle:IntPtr.Zero;}
  static bool? TryRaise(string expected){System.Diagnostics.Process[] all=null;try{all=System.Diagnostics.Process.GetProcessesByName("cloudmusic");if(all.Length==0)return null;var ids=new HashSet<int>();foreach(var p in all){try{if(String.Equals(p.MainModule.FileName,expected,StringComparison.OrdinalIgnoreCase))ids.Add(p.Id);}catch{}}if(ids.Count==0)return false;var windows=new List<WindowCandidate>();EnumWindows((window,arg)=>{uint pid;GetWindowThreadProcessId(window,out pid);if(!ids.Contains((int)pid))return true;var cls=new System.Text.StringBuilder(256);GetClassName(window,cls,cls.Capacity);if(cls.ToString()!="OrpheusBrowserHost")return true;Native.RECT r;if(!GetWindowRect(window,out r))return true;if(IsIconic(window)){var placement=new Placement{Length=(uint)System.Runtime.InteropServices.Marshal.SizeOf(typeof(Placement))};if(GetWindowPlacement(window,ref placement))r=placement.Normal;}var title=new System.Text.StringBuilder(512);GetWindowText(window,title,title.Capacity);windows.Add(new WindowCandidate{Handle=window,ProcessId=(int)pid,ClassName=cls.ToString(),Title=title.ToString(),Owned=GetWindow(window,4)!=IntPtr.Zero,Child=(GetWindowLong(window,-16)&0x40000000)!=0,Width=r.Right-r.Left,Height=r.Bottom-r.Top,Visible=IsWindowVisible(window)});return true;},IntPtr.Zero);IntPtr target=SelectMainWindow(windows,ids);if(target==IntPtr.Zero)return false;ShowWindowAsync(target,IsIconic(target)?9:5);return SetForegroundWindow(target);}catch{return false;}finally{if(all!=null)foreach(var p in all)p.Dispose();}}
  public static bool Open(){string file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),@"Netease\CloudMusic\cloudmusic.exe");var existing=RaiseRunning(file);if(existing.HasValue)return existing.Value;return File.Exists(file)&&OpenInstalled(file);}
 }
